// Канонический файл: n8n/sample/companies.csv
// Те же две вымышленные строки. Сеть не используется.
const SAMPLE_SOURCE = "n8n/sample/companies.csv";
const rows = [
  {
    "name": "Ласточка Упаковка",
    "domain": "lastochka-pack.example",
    "website_url": "https://lastochka-pack.example",
    "industry": "packaging",
    "region": "Карелия",
    "description": "Вымышленный цех картонной упаковки для локальной демонстрации LeadOps.",
    "source_url": "https://catalog.example/companies/lastochka-pack"
  },
  {
    "name": "Тихий Причал",
    "domain": "tihiy-prichal.example",
    "website_url": "https://tihiy-prichal.example",
    "industry": "logistics",
    "region": "Архангельская область",
    "description": "Вымышленная каботажная логистика для локальной демонстрации LeadOps. Контактов нет.",
    "source_url": "https://catalog.example/companies/tihiy-prichal"
  }
];

function normalizeDomain(value) {
  let domain = String(value || '').trim().toLowerCase();
  domain = domain.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  domain = domain.split(/[/?#]/)[0];
  domain = domain.replace(/:\d+$/, '');
  if (domain.startsWith('www.')) domain = domain.slice(4);
  domain = domain.replace(/\.$/, '');
  return domain;
}

return rows.map((row) => {
  const domain = normalizeDomain(row.domain || row.website_url);
  if (!domain || !domain.includes('.')) {
    throw new Error('Пустой или некорректный домен в строке выборки');
  }
  return {
    json: {
      name: String(row.name || '').trim(),
      domain,
      website_url: String(row.website_url || '').trim(),
      industry: String(row.industry || '').trim(),
      region: String(row.region || '').trim(),
      description: String(row.description || '').trim(),
      source_url: String(row.source_url || '').trim(),
      source: SAMPLE_SOURCE,
    },
  };
});
